content: """Edge-cache key normalization."""

import urllib.parse

TRACKING_PARAMS = {
    'gclid', 'fbclid', 'msclkid', 'dclid', 'gclsrc', 'ttclid', 'twclid', 'li_fat_id',
    'yclid', 'mc_cid', 'mc_eid', '_ga', '_ke', '_hsenc', '_hsmi', 'hsctatracking', 'sc_cid',
    'rtid', 'epik', 'dicbo', 'tblci'
}


def cache_key(url):
    """Normalize a URL into an edge-cache key."""
    url = url.strip()
    parsed = urllib.parse.urlsplit(url)

    scheme = parsed.scheme.lower()
    netloc = parsed.netloc.lower()
    path = parsed.path
    fragment = parsed.fragment

    query_str = parsed.query
    if query_str:
        parsed_params = urllib.parse.parse_qsl(query_str, keep_blank_values=True)
        filtered_params = []
        for name, value in parsed_params:
            if not value:
                continue
            name_lower = name.lower()
            if name_lower.startswith('utm_') and name_lower != 'utm_content':
                continue
            if name_lower in TRACKING_PARAMS:
                continue
            filtered_params.append((name, value))

        sorted_params = sorted(filtered_params, key=lambda x: x[0])
        if sorted_params:
            new_query = urllib.parse.urlencode(sorted_params, quote_via=urllib.parse.quote)
        else:
            new_query = ""
    else:
        new_query = ""

    return urllib.parse.urlunsplit((scheme, netloc, path, new_query, fragment))

