import csv
import io


def to_csv(rows, columns):
    """Render rows (list of dicts) as CSV text for the ERP import."""
    output = io.StringIO()
    writer = csv.writer(output, lineterminator='\r\n')

    # Write the header
    writer.writerow(columns)

    # Write the rows
    for row in rows:
        formatted_row = []
        for col in columns:
            val = row.get(col)
            if val is None:
                formatted_row.append("")
            else:
                s = str(val)
                if len(s) > 1 and s.startswith('0') and s.isdigit():
                    formatted_row.append('="{}"'.format(s))
                else:
                    formatted_row.append(s)
        writer.writerow(formatted_row)

    return output.getvalue()
