newString: """CSV writer for the ERP import."""


def to_csv(rows, columns):
    """Render rows (list of dicts) as CSV text for the ERP import."""

    def escape_field(val):
        if val is None:
            return ""
        s = str(val)
        if len(s) > 1 and s.startswith('0') and s.isdigit():
            return '="{}"'.format(s)

        has_quote = '"' in s
        has_comma = ',' in s
        has_newline = '\n' in s or '\r' in s

        if has_quote or has_comma or has_newline:
            escaped = s.replace('"', '""')
            return '"{}"'.format(escaped)

        return s

    lines = [",".join(escape_field(col) for col in columns)]
