newString: def merge_records(primary, incoming):
    """Merge incoming sync records into the primary list, dropping duplicate contacts."""
    seen = set()
    ordered_emails = []
    candidates_by_email = {}

    for rec in primary:
        email_raw = rec.get("email", "")
        email_lower = email_raw.lower()
        if email_lower not in seen:
            seen.add(email_lower)
            ordered_emails.append(email_lower)
        if email_lower not in candidates_by_email:
            candidates_by_email[email_lower] = []
        candidates_by_email[email_lower].append((rec, "primary"))

    for rec in incoming:
        email_raw = rec.get("email", "")
        email_lower = email_raw.lower()
        if email_lower not in seen:
            seen.add(email_lower)
            ordered_emails.append(email_lower)
        if email_lower not in candidates_by_email:
            candidates_by_email[email_lower] = []
        candidates_by_email[email_lower].append((rec, "incoming"))

    def get_richness(record):
        return sum(1 for k, v in record.items() if k not in ("email", "updated") and v is not None and v != "")

    def sort_key(item):
        record, source = item
        richness = get_richness(record)
        timestamp = record.get("updated", "")
        source_score = 1 if source == "primary" else 0
        return (richness, timestamp, source_score)

    out = []
    for email_lower in ordered_emails:
        candidates = candidates_by_email[email_lower]
        best_rec, _ = max(candidates, key=sort_key)
        out.append(best_rec)

    return out

