newString: def plan_waves(services):
    """Group services into ordered deployment waves (lists of service names)."""
    if not services:
        return []

    services_by_name = {s["name"]: s for s in services}
    canaries = [s for s in services if s.get("canary")]

    wave_memo = {}
    if canaries:
        for s in canaries:
            wave_memo[s["name"]] = 0

    min_wave = 1 if canaries else 0

    def compute_wave(name):
        if name in wave_memo:
            return wave_memo[name]

        # Fallback to prevent infinite recursion in case of cycle
        wave_memo[name] = min_wave

        svc = services_by_name.get(name)
        if not svc:
            # If dependency is not in services, assume satisfied
            wave_memo[name] = 0
            return 0

        deps = svc.get("deps", [])
        max_dep_wave = -1
        for dep in deps:
            if dep in services_by_name:
                dep_wave = compute_wave(dep)
                if dep_wave > max_dep_wave:
                    max_dep_wave = dep_wave

        wave = max_dep_wave + 1
        if wave < min_wave:
            wave = min_wave

        wave_memo[name] = wave
        return wave

    # Compute wave for all services
    for s in services:
        compute_wave(s["name"])

    max_wave = max(wave_memo[s["name"]] for s in services)
    waves = []
    for w in range(max_wave + 1):
        names_in_wave = [s["name"] for s in services if wave_memo[s["name"]] == w]
        if not names_in_wave:
            continue

        if w == 0 and canaries:
            names_in_wave.sort()
        else:
            names_in_wave.sort(key=lambda name: (services_by_name[name].get("tier", 0), name))

        waves.append(names_in_wave)

    return waves
