from collections.abc import Mapping


def merge_lists(a, b):
    res = list(a)
    seen = set()
    has_unhashable = False
    for x in a:
        try:
            seen.add(x)
        except TypeError:
            has_unhashable = True

    for x in b:
        if has_unhashable:
            if x not in res:
                res.append(x)
        else:
            try:
                if x not in seen:
                    seen.add(x)
                    res.append(x)
            except TypeError:
                has_unhashable = True
                if x not in res:
                    res.append(x)
    return res


def apply_updates(base, updates):
    result = dict(base)
    for key, value in updates.items():
        if key in result:
            base_val = result[key]
            if isinstance(base_val, Mapping) and isinstance(value, Mapping):
                result[key] = apply_updates(base_val, value)
            elif isinstance(base_val, list) and isinstance(value, list):
                result[key] = merge_lists(base_val, value)
            else:
                result[key] = value
        else:
            result[key] = value
    return result
