from boltons.iterutils import remap


def redact(event):
    """Mask sensitive fields in a log event."""
    def visit(path, key, value):
        if isinstance(key, str):
            key_lower = key.lower()
            if "card_number" in key_lower:
                val_str = str(value)
                tail = val_str[-4:] if len(val_str) >= 4 else val_str
                return key, "***" + tail
            elif any(s in key_lower for s in ("password", "token", "key", "secret", "ssn")):
                return key, "***"
        return key, value

    return remap(event, visit=visit)

