newString: def next_job(queue, last_tenant):
    """Pick the next job to run from the queue."""
    if not queue:
        return None

    # Avoid scheduling the same tenant twice in a row if other tenants are waiting
    has_other_tenants = any(j["tenant"] != last_tenant for j in queue)
    if has_other_tenants:
        candidates = [j for j in queue if j["tenant"] != last_tenant]
    else:
        candidates = queue

    return min(candidates, key=lambda j: (-j["priority"], j.get("est_runtime", 0), j["submitted_at"]))
