from auditlog import append_event, SequenceGapError, SequenceConflictError

def run_tests():
    # 1. test_first_event_must_be_seq_1
    ledger = {}
    try:
        append_event(ledger, {"tenant": "t1", "seq": 2, "type": "action", "payload_hash": "h1"})
        assert False, "Should raise SequenceGapError when first event is not seq 1"
    except SequenceGapError:
        pass

    # 2. test_compaction_advances_by_exactly_100
    ledger = {}
    append_event(ledger, {"tenant": "t1", "seq": 1, "type": "action", "payload_hash": "h1"})
    # Compaction of sequence 101 (1 + 100)
    assert append_event(ledger, {"tenant": "t1", "seq": 101, "type": "compaction", "payload_hash": "c1"}) is True

    # 3. test_compaction_with_any_other_jump_rejected
    ledger = {}
    append_event(ledger, {"tenant": "t1", "seq": 1, "type": "action", "payload_hash": "h1"})
    try:
        append_event(ledger, {"tenant": "t1", "seq": 102, "type": "compaction", "payload_hash": "c1"})
        assert False, "Should raise SequenceGapError for compaction jump other than 100"
    except SequenceGapError:
        pass

    try:
        append_event(ledger, {"tenant": "t1", "seq": 2, "type": "compaction", "payload_hash": "c1"})
        assert False, "Should raise SequenceGapError for compaction jump other than 100"
    except SequenceGapError:
        pass

    # 4. test_sequence_continues_after_compaction
    ledger = {}
    append_event(ledger, {"tenant": "t1", "seq": 1, "type": "action", "payload_hash": "h1"})
    append_event(ledger, {"tenant": "t1", "seq": 101, "type": "compaction", "payload_hash": "c1"})
    assert append_event(ledger, {"tenant": "t1", "seq": 102, "type": "action", "payload_hash": "h2"}) is True

    # 5. test_duplicate_with_matching_hash_is_a_noop
    ledger = {}
    append_event(ledger, {"tenant": "t1", "seq": 1, "type": "action", "payload_hash": "h1"})
    assert append_event(ledger, {"tenant": "t1", "seq": 1, "type": "action", "payload_hash": "h1"}) is False
