content: """SLA downtime accounting."""
from datetime import datetime, timedelta


def _t(s):
    return datetime.fromisoformat(s)


def merge_intervals(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0]]
    for current in intervals[1:]:
        prev_start, prev_end = merged[-1]
        curr_start, curr_end = current
        if curr_start <= prev_end:
            merged[-1] = (prev_start, max(prev_end, curr_end))
        else:
            merged.append(current)
    return merged


def downtime_minutes(incidents, maintenance):
    """Total SLA downtime in minutes for a billing period."""
    # Parse incidents
    inc_intervals = []
    for inc in incidents:
        start, end = _t(inc["start"]), _t(inc["end"])
        if start < end:
            inc_intervals.append((start, end))

    # Merge overlapping incidents
    merged_inc = merge_intervals(inc_intervals)

    # Filter out sub-minute blips (less than 60 seconds)
    non_blip_inc = []
    for start, end in merged_inc:
        if (end - start).total_seconds() >= 60.0:
            non_blip_inc.append((start, end))

    # Parse and filter valid maintenance windows
    maint_intervals = []
    for m in maintenance:
        m_start, m_end = _t(m["start"]), _t(m["end"])
        if m_start >= m_end:
            continue
        announced_at_str = m.get("announced_at")
        if announced_at_str:
            announced_at = _t(announced_at_str)
            if (m_start - announced_at) < timedelta(hours=24):
                continue
        else:
            continue
        maint_intervals.append((m_start, m_end))

    # Merge overlapping valid maintenance windows
    merged_maint = merge_intervals(maint_intervals)

    # Calculate downtime
    total_seconds = 0.0
    for start, end in non_blip_inc:
        span = (end - start).total_seconds()
        for m_start, m_end in merged_maint:
            lo = max(start, m_start)
            hi = min(end, m_end)
            overlap = max((hi - lo).total_seconds(), 0.0)
            span -= overlap
        total_seconds += span

    return total_seconds / 60.0

