from datetime import datetime, timedelta


def _t(s):
    return datetime.fromisoformat(s)


def downtime_minutes(incidents, maintenance):
    """Total SLA downtime in minutes for a billing period."""
    # 1. Parse and collect all incident intervals
    inc_intervals = []
    for inc in incidents:
        start = _t(inc["start"])
        end = _t(inc["end"])
        if end > start:
            inc_intervals.append((start, end))

    # 2. Merge overlapping or adjacent incident intervals
    if not inc_intervals:
        return 0.0

    inc_intervals.sort(key=lambda x: x[0])
    merged_inc = [inc_intervals[0]]
    for start, end in inc_intervals[1:]:
        prev_start, prev_end = merged_inc[-1]
        if start <= prev_end:
            merged_inc[-1] = (prev_start, max(prev_end, end))
        else:
            merged_inc.append((start, end))

    # 3. Filter out sub-minute blips (strictly less than 60 seconds)
    valid_inc = []
    for start, end in merged_inc:
        if (end - start).total_seconds() >= 60.0:
            valid_inc.append((start, end))

    # 4. Parse and collect all valid planned maintenance intervals
    maint_intervals = []
    for m in maintenance:
        start = _t(m["start"])
        end = _t(m["end"])
        if end <= start:
            continue
        announced_at_str = m.get("announced_at")
        if announced_at_str:
            announced_at = _t(announced_at_str)
            if start - announced_at >= timedelta(days=1):
                maint_intervals.append((start, end))

    # 5. Merge overlapping or adjacent maintenance intervals to avoid double-subtraction
    if maint_intervals:
        maint_intervals.sort(key=lambda x: x[0])
        merged_maint = [maint_intervals[0]]
        for start, end in maint_intervals[1:]:
            prev_start, prev_end = merged_maint[-1]
            if start <= prev_end:
                merged_maint[-1] = (prev_start, max(prev_end, end))
            else:
                merged_maint.append((start, end))
    else:
        merged_maint = []

    # 6. Subtract valid planned maintenance intervals from the incident intervals
    active_intervals = valid_inc[:]
    for m_start, m_end in merged_maint:
        next_active = []
        for s, e in active_intervals:
            if m_end <= s or m_start >= e:
                # No overlap
                next_active.append((s, e))
            else:
                # Overlap exists, potentially split the interval
                if m_start > s:
                    next_active.append((s, m_start))
                if m_end < e:
                    next_active.append((m_end, e))
        active_intervals = next_active

    # 7. Calculate total downtime in minutes
