newString: def merge_tags(sources):
    """Merge tag lists from every source into one combined list."""
    first_add = {}
    unique_tags_ordered = []
    for src_idx, tags in enumerate(sources):
        for tag in tags:
            if not tag.startswith("-"):
                tag_key = tag.lower()
                if tag_key not in first_add:
                    first_add[tag_key] = (src_idx, tag)
                    unique_tags_ordered.append(tag_key)

    first_tomb = {}
    for src_idx, tags in enumerate(sources):
        for tag in tags:
            if tag.startswith("-"):
                tag_key = tag[1:].lower()
                if tag_key not in first_tomb:
                    first_tomb[tag_key] = src_idx

    out = []
    for tag_key in unique_tags_ordered:
        add_idx, orig_tag = first_add[tag_key]
        tomb_idx = first_tomb.get(tag_key, float("inf"))
        if tomb_idx > add_idx:
            out.append(orig_tag)
    return out
