newString: def merge_tags(sources):
    """Merge tag lists from every source into one combined list."""
    out = []
    seen = set()
    active_tombstones = set()
    for tags in sources:
        current_tombstones = set()
        for tag in tags:
            if tag.startswith("-"):
                current_tombstones.add(tag[1:].lower())
            else:
                tag_lower = tag.lower()
                if tag_lower not in active_tombstones:
                    if tag_lower not in seen:
                        out.append(tag)
                        seen.add(tag_lower)
        active_tombstones.update(current_tombstones)
    return out
