def parse_quantity(value, kind):
    """Convert a config quantity like '512M' into bytes for the given
    resource kind ("memory" or "disk")."""
    s = str(value).strip()
    if not s:
        raise ValueError("empty value")

    if kind == "memory":
        units = _MEMORY_UNITS
        default_factor = 1024 ** 2
    elif kind == "disk":
        units = _DISK_UNITS
        default_factor = 1000 ** 3
    else:
        raise ValueError("unknown kind: " + str(kind))

    if s[-1].isalpha():
        suffix = s[-1].upper()
        if suffix not in units:
            raise ValueError("invalid unit suffix for " + kind + ": " + s[-1])
        try:
            num = int(s[:-1])
        except ValueError:
            raise ValueError("invalid quantity: " + s)
        return num * units[suffix]
    else:
        try:
            num = int(s)
        except ValueError:
            raise ValueError("invalid quantity: " + s)
        return num * default_factor
